const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const deltaGeometry = ee.Geometry.Polygon([
    [-89.5, 29.0],
    [-89.0, 29.0],
    [-89.0, 29.5],
    [-89.5, 29.5],
    [-89.5, 29.0]
  ]);

  const startDate = '2025-01-21';
  const endDate = '2025-01-25'; // exclusive

  // 2. Data Acquisition - MODIS Snow Cover
  const modisCol = ee.ImageCollection('MODIS/006/MOD10A1')
    .filterBounds(deltaGeometry)
    .filterDate(startDate, endDate)
    .select('NDSI_Snow_Cover');

  const colSize = modisCol.size().getInfo();
  print(`MODIS Snow Images: ${colSize}`);

  // Check for empty collection
  if (colSize === 0) {
    print("No MODIS snow data found.");
    print("<answer>C1</answer>");
    return;
  }

  // Create composite (max snow cover over the period)
  const composite = modisCol.max();

  // Mask out non-snow values (101-255 are clouds/no data/water etc.)
  // Values 0-100 represent snow cover percentage
  const snowMasked = composite.updateMask(composite.lte(100));

  // 3. Check valid pixels
  const pixelCount = snowMasked.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: deltaGeometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover').getInfo();

  print(`Valid pixels after masking: ${pixelCount}`);

  if (pixelCount === 0 || pixelCount === null) {
    print("No valid snow pixels in region.");
    print("<answer>C2</answer>");
    return;
  }

  // 4. Calculate mean snow cover
  const meanSnow = snowMasked.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: deltaGeometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover').getInfo();

  print(`Mean snow cover (%): ${meanSnow}`);

  // 5. Validation & Final Answer
  if (meanSnow === null || meanSnow === undefined || meanSnow < 0 || meanSnow > 100) {
    print("Invalid snow cover value.");
    print("<answer>C3</answer>");
  } else if (meanSnow > 0) {
    print("Snow detected in region.");
    print("<answer>A</answer>");
  } else {
    print("No snow detected.");
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
